import threading
import time

class StampedeCache:
    def __init__(self):
        self.cache = {} # key -> (value, expires_at)
        self.flights = {} # key -> threading.Lock (represents an in-progress load)
        self.lock = threading.Lock()

    def get_or_compute(self, key, loader, ttl_seconds, now=None):
        # Strict type validation
        if isinstance(ttl_seconds, bool) or not isinstance(ttl_seconds, (int, float)):
            raise TypeError("ttl_seconds must be a number (int or float), not bool")
        if not callable(loader):
            raise TypeError("loader must be callable")
        if not isinstance(key, str) or not key:
            raise ValueError("key must be a non-empty string")
        if now is None:
            now = time.time()
        elif isinstance(now, bool) or not isinstance(now, (int, float)):
            raise TypeError("now must be a number (int or float), not bool")

        # Check cache first
        with self.lock:
            if key in self.cache:
                val, expires_at = self.cache[key]
                if expires_at > now:
                    return val

        # Single-flight coalescing
        with self.lock:
            # Check again in case another thread updated it while we were waiting for the lock
            if key in self.cache:
                val, expires_at = self.cache[key]
                if expires_at > now:
                    return val

            if key in self.flights:
                # Another thread is already loading this key. Wait for it to finish.
                flight_lock = self.flights[key]
                is_leader = False
            else:
                # This thread is the leader. Create a lock for this flight.
                flight_lock = threading.Lock()
                self.flights[key] = flight_lock
                is_leader = True

        if is_leader:
            try:
                # Execute the loader outside the main lock
                val = loader()

                with self.lock:
                    self.cache[key] = (val, now + ttl_seconds)
                    # Clean up the flight marker
                    if key in self.flights and self.flights[key] is flight_lock:
                        del self.flights[key]
            except Exception as e:
                with self.lock:
                    # Clean up the flight marker on failure so future calls can retry
                    if key in self.flights and self.flights[key] is flight_lock:
                        del self.flights[key]
                raise e
            return val
        else:
            # Wait for the leader to finish
            flight_lock.acquire()
            try:
                # The leader has updated the cache and released the flight lock.
                # We can now safely read the cache.
                with self.lock:
                    val, _ = self.cache[key]
                    return val
            finally:
                flight_lock.release()

